    tr = T.get('full_five_hop_traversal_rate_active', T.get('full_five_hop_traversal_rate')); bp = T.get('lexical_bypass_rate_active', T.get('lexical_bypass_rate_strict', T.get('lexical_bypass_rate')))
    tbl.append(f"| {name} | {tgt} | {C.get('acc_at_1_completed', C.get('acc_at_1'))} ({cn}) | {T.get('acc_at_1_completed', T.get('acc_at_1'))} ({tn}) | {C.get('first_gold_step_mean')} (n={cg}) | {T.get('first_gold_step_mean')} (n={tg}) | {C.get('tool_calls_mean_completed', C.get('tool_calls_mean'))} / {C.get('tool_calls_mean_active', C.get('tool_calls_mean'))} (n={ca}) | {T.get('tool_calls_mean_completed', T.get('tool_calls_mean'))} / {T.get('tool_calls_mean_active', T.get('tool_calls_mean'))} (n={ta}) | {tr} (n={ta}) | {bp} (n={ta}) |")
